&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Une connaissance des approches Specification-Driven Development (SDD) et des pratiques d&#39;ingénierie logicielle associées.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Une familiarité avec les outils de développement assisté par IA generative.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
