&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;We recruit a small group of Fellows each round, with the next fellowship starting in January 2027.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;The cohort gives you a group of peers from day one and gives us a regular way to bring exceptional technical talent into Baringa. It sits between traditional Early Careers and experienced hiring: you don&#39;t need years of experience, but you do need the technical depth to contribute from the start.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h2 data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559683&amp;quot;:0,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559731&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335562764&amp;quot;:2,&amp;quot;335562765&amp;quot;:1,&amp;quot;335562766&amp;quot;:4,&amp;quot;335562767&amp;quot;:0,&amp;quot;335562768&amp;quot;:4,&amp;quot;335562769&amp;quot;:5}&quot;&gt;&lt;span data-scheme-color=&quot;@8E63E8,,&quot; data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt;How To Join&lt;/span&gt;&lt;/h2&gt;
&lt;ol&gt;
&lt;li&gt;​&lt;strong&gt;&lt;span data-scheme-color=&quot;@FFFFFF,,&quot; data-usefontface=&quot;true&quot; data-contrast=&quot;none&quot;&gt;Apply&lt;/span&gt;&lt;/strong&gt;​ - Te&lt;span class=&quot;NormalTextRun SCXW12450175 BCX8&quot;&gt;ll us about your background, technical &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW12450175 BCX8&quot;&gt;interests&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW12450175 BCX8&quot;&gt; and the work &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW12450175 BCX8&quot;&gt;you’re&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW12450175 BCX8&quot;&gt; proud of.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;
&lt;p data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559683&amp;quot;:0,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559731&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335562764&amp;quot;:2,&amp;quot;335562765&amp;quot;:1,&amp;quot;335562766&amp;quot;:4,&amp;quot;335562767&amp;quot;:4,&amp;quot;335562768&amp;quot;:4,&amp;quot;335562769&amp;quot;:0}&quot;&gt;&lt;strong&gt;&lt;span data-scheme-color=&quot;@FFFFFF,,&quot; data-usefontface=&quot;true&quot; data-contrast=&quot;none&quot;&gt;Technical assessment &lt;/span&gt;&lt;/strong&gt;&lt;span data-scheme-color=&quot;@FFFFFF,,&quot; data-usefontface=&quot;true&quot; data-contrast=&quot;none&quot;&gt;- &lt;span data-scheme-color=&quot;@D7DCE8,,&quot; data-usefontface=&quot;true&quot; data-contrast=&quot;none&quot;&gt;A&amp;nbsp;&lt;span class=&quot;TextRun SCXW146267544 BCX8&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW146267544 BCX8&quot;&gt; focused assessment designed to understand how you approach technical problems, not just what you already know.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559683&amp;quot;:0,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559731&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335562764&amp;quot;:2,&amp;quot;335562765&amp;quot;:1,&amp;quot;335562766&amp;quot;:4,&amp;quot;335562767&amp;quot;:4,&amp;quot;335562768&amp;quot;:4,&amp;quot;335562769&amp;quot;:0}&quot;&gt;&lt;strong&gt;&lt;span data-scheme-color=&quot;@FFFFFF,,&quot; data-usefontface=&quot;true&quot; data-contrast=&quot;none&quot;&gt;Meet the team &lt;/span&gt;&lt;/strong&gt;&lt;span data-scheme-color=&quot;@FFFFFF,,&quot; data-usefontface=&quot;true&quot; data-contrast=&quot;none&quot;&gt;- &lt;span data-scheme-color=&quot;@D7DCE8,,&quot; data-usefontface=&quot;true&quot; data-contrast=&quot;none&quot;&gt;A&lt;span class=&quot;TextRun SCXW78172295 BCX8&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW78172295 BCX8&quot;&gt;n assessment day with people from our AI team to explore your technical thinking, consulting potential and fit.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559683&amp;quot;:0,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559731&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335562764&amp;quot;:2,&amp;quot;335562765&amp;quot;:1,&amp;quot;335562766&amp;quot;:4,&amp;quot;335562767&amp;quot;:4,&amp;quot;335562768&amp;quot;:4,&amp;quot;335562769&amp;quot;:0}&quot;&gt;&lt;strong&gt;&lt;span data-scheme-color=&quot;@FFFFFF,,&quot; data-usefontface=&quot;true&quot; data-contrast=&quot;none&quot;&gt;Join the cohort -&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-scheme-color=&quot;@FFFFFF,,&quot; data-usefontface=&quot;true&quot; data-contrast=&quot;none&quot;&gt;&lt;span data-scheme-color=&quot;@D7DCE8,,&quot; data-usefontface=&quot;true&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;TextRun SCXW100084345 BCX8&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW100084345 BCX8&quot;&gt;Successful candidates join the next available intake.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;​&lt;/p&gt;
&lt;p data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559683&amp;quot;:0,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559731&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335562764&amp;quot;:2,&amp;quot;335562765&amp;quot;:1,&amp;quot;335562766&amp;quot;:4,&amp;quot;335562767&amp;quot;:4,&amp;quot;335562768&amp;quot;:4,&amp;quot;335562769&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/p&gt;
