&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;52&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;8&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;If&amp;nbsp;you’re&amp;nbsp;talented and driven,&amp;nbsp;you’ll&amp;nbsp;own important problems early.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;52&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;9&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;5 days off&amp;nbsp;and annual stipends for&amp;nbsp;learning and development, and&amp;nbsp;funding for conferences and external collaborations.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;52&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;10&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Freedom to pursue research bets without product pressure.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;52&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;11&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Opportunities to publish and collaborate externally.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Life &amp;amp; family*&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;52&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;12&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Modern central London office, or where applicable, option to work in similar government offices in Birmingham, Cardiff, Darlington, Edinburgh, Salford or Bristol.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;52&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;13&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Hybrid working, flexibility for occasional remote work abroad and stipends for work-from-home equipment.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;52&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;14&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;At least 25 days’ annual leave, 8 public holidays, extra team-wide&amp;nbsp;breaks&amp;nbsp;and 3 days off for volunteering.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;52&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;15&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Generous paid parental leave (36 weeks of UK statutory leave shared between parents + 3 extra paid weeks + option for&amp;nbsp;additional&amp;nbsp;unpaid time).&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;52&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;16&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;On top of your salary, we contribute 28.97% of your base salary to your pension.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;52&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;17&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Discounts and benefits for cycling to work, donations and retail/gyms.&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;*These benefits apply to direct employees. Benefits may differ for individuals joining through other employment arrangements such as secondments.&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h2&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Salary&lt;/span&gt;&lt;/h2&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Annual salary is benchmarked to role scope and relevant experience. Most offers land between £65,000 and £145,000 made up of a base salary plus a technical allowance (take-home salary = base + technical allowance). An additional 28.97% employer pension contribution is paid on the base salary.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;This role sits outside of the&amp;nbsp;&lt;/span&gt;&lt;a href=&quot;https://ddat-capability-framework.service.gov.uk/&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;DDaT pay framework&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;given the scope of this role requires in depth technical&amp;nbsp;expertise&amp;nbsp;in frontier AI safety,&amp;nbsp;robustness&amp;nbsp;and advanced AI architectures.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The full range of salaries are available below:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Level 3:&lt;/strong&gt; £65,000–£75,000 (Base £40,850 + Technical Allowance £24,150–£34,150)&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Level 4:&lt;/strong&gt; £85,000–£95,000 (Base £48,540 + Technical Allowance £36,460–£46,460)&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Level 5:&lt;/strong&gt; £105,000–£115,000 (Base £63,165 + Technical Allowance £41,835–£51,835)&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Level 6:&lt;/strong&gt; £125,000–£135,000 (Base £76,475 + Technical Allowance £48,525–£58,525)&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Level 7:&lt;/strong&gt; £145,000 (Base £76,475 + Technical Allowance £68,525)&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h4&gt;Additional Information&lt;/h4&gt;
&lt;div class=&quot;vac_display_field&quot;&gt;
&lt;div class=&quot;vac_display_nullclass&quot;&gt;
&lt;h3&gt;&lt;span style=&quot;font-size: 8pt;&quot;&gt;&lt;strong&gt;Use of AI in Applications&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 8pt;&quot;&gt;Artificial Intelligence can be a useful tool to support your application, however, all examples and statements provided must be truthful, factually accurate and taken directly from your own experience. Where plagiarism has been identified (presenting the ideas and experiences of others, or generated by artificial intelligence, as your own) applications may be withdrawn and internal candidates may be subject to disciplinary action. Please see our&amp;nbsp;&lt;u&gt;&lt;a href=&quot;https://eur02.safelinks.protection.outlook.com/?url=https%3A%2F%2Fwww.civil-service-careers.gov.uk%2Fartificial-intelligence-and-recruitment%2F&amp;amp;data=05%7C02%7CLynn.Tan%40dsit.gov.uk%7Ccf5d753b7f19427afc8f08de4c307014%7Ccbac700502c143ebb497e6492d1b2dd8%7C0%7C0%7C639031968075235036%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&amp;amp;sdata=jCrYoy62YfXN%2FLIB%2FhtHxdLGbCOgropbkZXDyQsUMC4%3D&amp;amp;reserved=0&quot; target=&quot;_blank&quot; data-outlook-id=&quot;02db05e7-03ca-4ca6-bcd9-73ff8bf258f2&quot; data-auth=&quot;NotApplicable&quot; data-linkindex=&quot;1&quot;&gt;candidate guidance&amp;nbsp;&lt;/a&gt;&lt;/u&gt;for more information on appropriate and inappropriate use.&lt;br&gt;&lt;br&gt;&lt;strong&gt;Use of AI tools in recruitment&lt;em&gt; &lt;/em&gt;&lt;/strong&gt;&lt;br&gt;&lt;br&gt;We may use AI tools to help our hiring teams review applications, for example by summarising application materials and helping us prioritise applications against the published criteria.&amp;nbsp;People make every decision. AI tools do not decide the outcome of any application. Every decision is made by a member of our hiring team, and we do not make solely automated decisions about candidates.&amp;nbsp;We only use the information you provide in your application. We do not use AI tools to collect information about you from other sources, including the internet. These tools are approved for use within AISI and operate in our secure environment. We process this information in line with our wider recruitment retention policy. You can ask how AI was used in relation to your application, request a human review, or object to AI being used, by contacting the hiring manager. This will not affect how your application is assessed.&lt;br&gt;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;font-size: 8pt;&quot;&gt;&lt;strong&gt;Internal Fraud Database&lt;/strong&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 8pt;&quot;&gt;The Internal Fraud function of the Fraud, Error, Debt and Grants Function at the Cabinet Office processes details of civil servants who have been dismissed for committing internal fraud, or who would have been dismissed had they not resigned. The Cabinet Office receives the details from participating government organisations of civil servants who have been dismissed, or who would have been dismissed had they not resigned, for internal fraud. In instances such as this, civil servants are then banned for 5 years from further employment in the civil service. The Cabinet Office then processes this data and discloses a limited dataset back to DLUHC as a participating government organisations. DLUHC then carry out the pre employment checks so as to detect instances where known fraudsters are attempting to reapply for roles in the civil service. In this way, the policy is ensured and the repetition of internal fraud is prevented.&amp;nbsp; &lt;/span&gt;&lt;span style=&quot;font-size: 8pt;&quot;&gt;For more information please see -&amp;nbsp;&lt;a href=&quot;https://www.gov.uk/government/publications/internal-fraud-register-privacy-notice/internal-fraud-register-privacy-notice&quot;&gt;Internal Fraud Register.&lt;/a&gt;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;font-size: 8pt;&quot;&gt;Security&lt;/span&gt;&lt;/h3&gt;
&lt;span style=&quot;font-size: 8pt;&quot;&gt;Successful candidates must undergo a criminal record check and get&amp;nbsp;&lt;a class=&quot;c-link&quot; href=&quot;https://www.gov.uk/government/publications/government-baseline-personnel-security-standard&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://www.gov.uk/government/publications/government-baseline-personnel-security-standard&quot; data-sk=&quot;tooltip_parent&quot;&gt;baseline personnel security standard (BPSS)&amp;nbsp;clearance&lt;/a&gt;&amp;nbsp;before they can be appointed. Additionally, there is a strong preference for eligibility for&amp;nbsp;&lt;a class=&quot;c-link&quot; href=&quot;https://www.gov.uk/government/publications/national-security-vetting-advice-for-people-who-are-being-vetted&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://www.gov.uk/government/publications/national-security-vetting-advice-for-people-who-are-being-vetted&quot; data-sk=&quot;tooltip_parent&quot;&gt;counter-terrorist check (CTC)&amp;nbsp;clearance&lt;/a&gt;. Some roles may require higher levels of clearance, and we will state this by exception in the job advertisement.&amp;nbsp;&lt;a class=&quot;c-link&quot; href=&quot;https://www.gov.uk/government/publications/vetting-explained-and-our-vetting-charter/the-vetting-charter&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://www.gov.uk/government/publications/vetting-explained-and-our-vetting-charter/the-vetting-charter&quot; data-sk=&quot;tooltip_parent&quot;&gt;See our vetting charter here.&lt;/a&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;vac_display_field&quot;&gt;
&lt;h3&gt;&lt;span style=&quot;font-size: 8pt;&quot;&gt;Nationality requirements&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 8pt;&quot;&gt;We may be able to offer roles to applicant from &lt;strong&gt;any nationality or background&lt;/strong&gt;. As such we encourage you to apply even if you do not meet the standard &lt;a href=&quot;https://www.gov.uk/government/publications/nationality-rules&quot; target=&quot;_blank&quot;&gt;nationality requirements (opens in a new window).&lt;/a&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;vac_display_field&quot;&gt;
&lt;h3&gt;&lt;span style=&quot;font-size: 8pt;&quot;&gt;Working for the Civil Service&lt;/span&gt;&lt;/h3&gt;
&lt;div class=&quot;vac_display_field&quot;&gt;
&lt;div class=&quot;vac_display_field_value&quot;&gt;&lt;span style=&quot;font-size: 8pt;&quot;&gt;The&amp;nbsp;&lt;a href=&quot;http://civilservicecommission.independent.gov.uk/code/&quot; target=&quot;_blank&quot;&gt;Civil Service Code (opens in a new window)&lt;/a&gt; sets out the standards of behaviour expected of civil servants.&amp;nbsp;The Civil Service embraces diversity and promotes equal opportunities. As such, we run a Disability Confident Scheme (DCS) for candidates with disabilities who meet the minimum selection criteria.&amp;nbsp;The Civil Service also offers a Redeployment Interview Scheme to civil servants who are at risk of redundancy, and who meet the minimum requirements for the advertised vacancy.&lt;/span&gt;&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;vac_display_field&quot;&gt;
&lt;h3&gt;&lt;span style=&quot;font-size: 8pt;&quot;&gt;Diversity and Inclusion&lt;/span&gt;&lt;/h3&gt;
&lt;div class=&quot;vac_display_field_value&quot;&gt;&lt;span style=&quot;font-size: 8pt;&quot;&gt;The Civil Service is committed to attract, retain and invest in talent wherever it is found. To learn more please see the&amp;nbsp;&lt;a href=&quot;https://www.gov.uk/government/publications/civil-service-people-plan-2024-2027/civil-service-people-plan-2024-2027-html&quot; target=&quot;_blank&quot;&gt;Civil Service People Plan (opens in a new window)&lt;/a&gt;&amp;nbsp;and the&amp;nbsp;&lt;a href=&quot;https://www.gov.uk/government/publications/civil-service-diversity-and-inclusion-strategy-2022-to-2025&quot; target=&quot;_blank&quot;&gt;Civil Service Diversity and Inclusion Strategy (opens in a new window)&lt;/a&gt;. As part of the application process, we monitor statistics on D&amp;amp;I. You can see how we process this data here: &lt;a href=&quot;https://www.gov.uk/government/publications/government-digital-service-recruitment-privacy-notice/recruitment-privacy-notice&quot; target=&quot;_blank&quot;&gt;Recruitment privacy notice - GOV.UK&lt;/a&gt;.&lt;/span&gt;&lt;/div&gt;
&lt;/div&gt;&lt;/div&gt;Find Jobs in United Kingdom on Arbeitnow

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Cambridge, UK | Full-time or Part-time | Permanent (or Temporary) | Hybrid&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Salary: £80,000 - £100,000 DOE &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;The salary range for this role is broad, as we are able to consider varying levels of experience.&amp;nbsp;&amp;nbsp;Any offer made will carefully take into account level of experience (including relevant industry experience), transferable relevant skills and previous relevant achievements.&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;About us&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;Riverlane’s&amp;nbsp;mission is to master quantum error correction (QEC) and unlock a new age of human progress. From advances in material and climate science, to complex chemistry simulation for new drug design, quantum computers will help humanity solve some of its most important challenges. But without QEC, the industry’s defining technical challenge, such breakthroughs can never be achieved.&amp;nbsp;&amp;nbsp;Riverlane is the world leader in QEC technology. QEC is a complex problem that requires a range of skills,&amp;nbsp;talent&amp;nbsp;and passion.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW243923852 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW243923852 BCX8&quot;&gt;Having raised more than $125M in funding to date to accelerate our&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW243923852 BCX8&quot;&gt;cutting-edge&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW243923852 BCX8&quot;&gt;&amp;nbsp;R&amp;amp;D in quantum error correction (QEC), Riverlane partners with many of the world’s leading quantum hardware providers and government agencies to make fault-tolerant quantum computing a reality.&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW243923852 BCX8&quot;&gt;We’re&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW243923852 BCX8&quot;&gt;&amp;nbsp;making remarkable progress and growing fast. &lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW243923852 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About the role&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The Senior Embedded Systems Software Engineer bridges the gap between Riverlane and its customers. They act as the primary technical interface for customer’s engineers and guide them through product integration and help with trouble shooting complex quantum systems.&lt;br&gt;&lt;br&gt;As an Embedded Software Engineer on the Systems Team, you will configure our Deltaflow Hardware to connect to the Quantum Computer allowing it to provide a low-latency, high throughput system that performs complex operations in a predictable and guaranteed way. You will develop our software stack to work with customers quantum computers. You will ensure our customers can run quantum experiments, implement Riverlane’s quantum errors correction algorithm and debug any issues that arise.&lt;br&gt;&lt;br&gt;This is a fantastic opportunity to join a team that is developing the world’s most advanced quantum error correcting algorithms and QEC Hardware. The Riverlane team is a mix of mathematicians, physicists and engineers, working together on a range of exciting and cutting-edge QEC projects.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What you will do:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Technical Pre / Post-Sales:&lt;br&gt;&amp;nbsp; &amp;nbsp;-Host Technical Workshops on Riverlane’s QEC Stack and DeltaKit.&lt;br&gt;&amp;nbsp; &amp;nbsp;-Evaluate Customers Software and data communication systems.&lt;/li&gt;
&lt;li&gt;Integration On-Site: End-to-End System Deployment.&lt;br&gt;&amp;nbsp; &amp;nbsp;-Integrate our Software Stack into Customer’s Quantum Computer Systems.&lt;br&gt;&amp;nbsp; &amp;nbsp;-Work with Riverlane’s Quantum Application Team to design experiments to test the compiled software.&lt;br&gt;&amp;nbsp; &amp;nbsp;-Benchmark and discover system limitations.&lt;/li&gt;
&lt;li&gt;Troubleshooting and Debugging: Managing Customer Issues&lt;br&gt;&amp;nbsp; &amp;nbsp;-Report issues and help replicate the setup with the QA team in Riverlane.&lt;br&gt;&amp;nbsp; &amp;nbsp;-Writing scripts to help debug the complete system&lt;br&gt;&amp;nbsp; &amp;nbsp;-Update test environment and document the experiments that were conducted.&lt;/li&gt;
&lt;li&gt;Customer Advocacy: Voice of the Customer to River Lane Product Team&lt;br&gt;&amp;nbsp; &amp;nbsp;-Highlight the success, issues and trends on customer’s Quantum Systems&lt;br&gt;&amp;nbsp; &amp;nbsp;-Feedback key features that will be needed to win current and next generation products&lt;br&gt;&amp;nbsp; &amp;nbsp;-Create Dashboard that would allow better understanding of the complete quantum computing system.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What we need:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;A Bachelor&#39;s degree (or equivalent) in Computer Science, Electronic Engineering,&amp;nbsp;Physics, Math or a related discipline.&lt;/li&gt;
&lt;li&gt;Great communication skills (written and verbal) and an ability to work with a diverse range of people are essential.&lt;/li&gt;
&lt;li&gt;Strong experience of at least one Embedded Software programming language (C, C++, Python, etc.)&lt;/li&gt;
&lt;li&gt;Proven experience in SoC design, Embedded Systems Design, or Computer Architecture&lt;/li&gt;
&lt;li&gt;Proficiency with a scripting language, such as Python (preferred)&lt;/li&gt;
&lt;li&gt;Working knowledge of Verilog, VHDL or System Verilog preferred&lt;/li&gt;
&lt;li&gt;Curiosity to learn about new technologies, including quantum computing and error&amp;nbsp;correction&lt;/li&gt;
&lt;li&gt;A deep understanding of how hardware implements with software&lt;/li&gt;
&lt;li&gt;Experience with standard development practices, such as source control, continuous integration, unit testing, and standard debug methodologies&lt;/li&gt;
&lt;li&gt;Ability to work well within a team and independently&lt;/li&gt;
&lt;li&gt;Experience mentoring junior embedded Software Engineers (this is not a people manager role)&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Even better if you have:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience working on scientific instrumentation&lt;/li&gt;
&lt;li&gt;Good knowledge of Quantum Mechanics&lt;/li&gt;
&lt;li&gt;Technical pre / post sales, professional services or field application engineering experience&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;What can you expect from us&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A comprehensive benefits package that includes&amp;nbsp;an annual bonus plan,&amp;nbsp;private medical insurance, life insurance, and a&amp;nbsp;contributory pension scheme&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Equity, so that our team can share in the long-term success of Riverlane&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;28 days annual leave,&amp;nbsp;plus bank holidays and enhanced family leave&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A diverse work environment that brings together experts in many fields (including software and hardware development, quantum information theory,&amp;nbsp;physics&amp;nbsp;and maths) and over 20 different nationalities&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;5&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A learning environment that encourages individual, team and company growth and&amp;nbsp;development, including a regular programme of learning events and training and conference budgets&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;How to apply&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Please upload a CV and covering letter by clicking &#39;Apply&#39;. Your covering letter should explain why you are applying for the job and what skills and experience you can bring to the role.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We review CVs as we receive them and interview as soon as we have applications that&amp;nbsp;look&amp;nbsp;like a good match. We do not use closing dates. So, please&amp;nbsp;apply as soon as possible to avoid&amp;nbsp;missing out on&amp;nbsp;this role.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;If you have any queries, please contact&amp;nbsp;&lt;/span&gt;&lt;a ----- data-contrast=&quot;none&quot;&gt;&lt;span ----- data-ccp-charstyle=&quot;Hyperlink&quot;&gt;com&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Everyone is welcome at Riverlane. We are an equal opportunities employer and encourage applications from eligible and suitably qualified candidates regardless of age, disability, ethnicity, gender, gender reassignment, religion or belief, sexual orientation, marital or civil partnership status, or pregnancy and maternity/paternity.&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;Women and other underrepresented groups may be less likely to apply for a role unless they meet all or&amp;nbsp;nearly all&amp;nbsp;of the requirements.&amp;nbsp;&amp;nbsp;If this applies to you, we still encourage you to apply - you may be a great fit, even if you&amp;nbsp;don’t&amp;nbsp;meet every single qualification.&amp;nbsp;We’d&amp;nbsp;love to hear from you.&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;If you need any adjustments made to the application or selection process so you can do your best, please let us know. We will be happy to help.&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;GDPR notice: Riverlane collects and processes personal data in accordance with applicable data protection laws. If you are a European Job Applicant see the&amp;nbsp;&lt;strong&gt;&lt;a id=&quot;OWA843b0309-1485-8922-978c-b4a29d28b8a6&quot; class=&quot;x_x_fui-Link x_x____1q1shib x_x_f2hkw1w x_x_f3rmtva x_x_f1ewtqcl x_x_fyind8e x_x_f1k6fduh x_x_f1w7gpdv x_x_fk6fouc x_x_fjoy568 x_x_figsok6 x_x_f1s184ao x_x_f1mk8lai x_x_fnbmjn9 x_x_f1o700av x_x_f13mvf36 x_x_f1cmlufx x_x_f9n3di6 x_x_f1ids18y x_x_f1tx3yz7 x_x_f1deo86v x_x_f1eh06m1 x_x_f1iescvh x_x_fhgqx19 x_x_f1olyrje x_x_f1p93eir x_x_f1nev41a x_x_f1h8hb77 x_x_f1lqvz6u x_x_f10aw75t x_x_fsle3fq x_x_f17ae5zn x_x_OWAAutoLink&quot; href=&quot;https://riverlane.workable.com/gdpr_policy/v1?lang=en&quot; data-auth=&quot;NotApplicable&quot; data-linkindex=&quot;1&quot;&gt;privacy notice&lt;/a&gt;&lt;/strong&gt;&amp;nbsp;for further details.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;Find Jobs in United Kingdom on Arbeitnow

&lt;p&gt;Captify, now part of Verve Group, is the leading Search Intelligence Platform for the open web and the largest independent holder of first-party search data outside of Google, connecting the real-time searches from over 2 billion devices globally. Its Search Intelligence technology powers omnichannel programmatic advertising and real-time insights for the world’s biggest brands, such as Disney, Unilever, eBay, Mercedes-Benz, Microsoft, Nestlé, GSK, Uber, Mars, P&amp;amp;G, Sony and Toyota—without reliance on third-party cookies. Captify brings brands more customers, publishers greater yield and consumers the most relevant digital experiences.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Overview&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;This is an exciting opportunity to join Captify, the Global Leader in Search Intelligence. Captify is on the hunt for a Senior Sales Manager to help fuel our business in the UK, with a focus on driving growth across our Omnicom agency Network.The Senior Sales Manager will be based in our London office and working in a sales team with some of the most talented, hardworking &amp;amp; best characters in the media industry.&lt;/p&gt;
&lt;p&gt;The ideal candidate will have contacts within the Omnicom agency network, relationships they can lean on to build upon the positive momentum we are seeing at this agency holdco in 2026.&lt;/p&gt;
&lt;p&gt;As an integral member of the UK market team, you will play a major role in driving new business and account development revenue into the business and shaping the perception of the Captify business.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;em&gt;This is a hybrid position in our London office with 3 days in the office (Covent Garden).&lt;/em&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What we&#39;re looking for&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;You’ll be a digital media professional with 1-3 years of experience in the programmatic market either at a media agency or within media sales.&lt;/li&gt;
&lt;li&gt;Proficient in confidently pitching and identifying new growth opportunities, and a background in collaborating across teams, in particular trading desks.&lt;/li&gt;
&lt;li&gt;You’ll be an out-going and fun team member, with exceptional organisational and communication skills, coupled with a self-starter mindset and intuitive motivation.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What you’ll be doing:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Sourcing, pitching and closing programmatic revenue opportunities&lt;/li&gt;
&lt;li&gt;Grow Revenue from existing and new accounts&lt;/li&gt;
&lt;li&gt;Own agency patch and manage all levels of seniority across the patch supported by the sales leads&lt;/li&gt;
&lt;li&gt;Update Salesforce regularly to give the business an accurate view of expected revenue from your account list&lt;/li&gt;
&lt;li&gt;Respond to agency briefs with the support of other commercial teams and sales leads&lt;/li&gt;
&lt;li&gt;Provide regular feedback into the business on what our key brands are looking for from partners&lt;/li&gt;
&lt;li&gt;Remain up to date on industry trends and opportunities to ensure Captify sales team are better suited than key competitors&lt;/li&gt;
&lt;li&gt;Work closely with Account Managers and Traders to grow accounts through best in class customer service&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;KPI’s include:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Driving meetings and opportunities from named account list&lt;/li&gt;
&lt;li&gt;Driving Revenue growth from existing accounts&lt;/li&gt;
&lt;li&gt;Winning new logos and cross selling opportunities&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What you need to be successful:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;1-3 years Sales experience within Ad Tech / Programmatic landscape&lt;/li&gt;
&lt;li&gt;Connections with UK agency partners are highly desirable, particularly Omnicom agencies.&lt;/li&gt;
&lt;li&gt;Experience working with cross-functional teams and building relationships across internal teams&lt;/li&gt;
&lt;li&gt;Highly motivated individual with track record of outperforming revenue targets&lt;/li&gt;
&lt;li&gt;Highly experienced in digital advertising, enterprise solutions, online media buying and selling processes, and advertising technologies.&lt;/li&gt;
&lt;li&gt;Exceptional organisational and communication skills&lt;/li&gt;
&lt;li&gt;Confident in forecasting &amp;amp; budgeting&lt;/li&gt;
&lt;li&gt;Ability to work well under pressure whilst steering multiple workstreams&lt;/li&gt;
&lt;li&gt;A team player with an entrepreneurial attitude and strong will to succeed&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What We Offer&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Just a few of the benefits waiting for you at Verve:&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Stay healthy with our&lt;strong&gt;&amp;nbsp;Bupa HealthCare Plan&lt;/strong&gt;&amp;nbsp;with easy access to medical care&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Support your long-term financial security with our &lt;strong&gt;Aviva Corporate Pension Scheme&lt;/strong&gt;, with Verve contributing 3% of your qualifying earnings&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Pick what matters most to you in our&amp;nbsp;&lt;strong&gt;Personalized Benefits Platform,&amp;nbsp;&lt;/strong&gt;with a budget of&lt;strong&gt;&amp;nbsp;&amp;nbsp;&lt;/strong&gt;£50/month&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Recharge with&amp;nbsp;&lt;strong&gt;25 paid vacation days + 3 Wellness days&amp;nbsp;&lt;/strong&gt;throughout the year, in addition to the public holidays&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Boost your professional knowledge with our annual training budget &amp;amp; internal webinars&lt;/strong&gt;… and even more reasons to join us!&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-size: 8pt;&quot;&gt;Verve provides equal employment opportunities to all employees and applicants for employment and prohibits discrimination and harassment of any type without regard to race, color, religion, age, sex, national origin, disability status, genetics, protected veteran status, sexual orientation, gender identity or expression, or any other characteristic protected by federal, state or local laws.&amp;nbsp;&lt;br&gt;&lt;br&gt;If you are a California resident subject to the California Consumer Privacy Act, &lt;a href=&quot;https://verve.com/california-applicant-privacy-notice/&quot; target=&quot;_blank&quot;&gt;click here&lt;/a&gt; to understand how Verve processes your personal information and how you can exercise your rights.&lt;br&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 8pt;&quot;&gt;If you are located in the EU or UK visit our&amp;nbsp;&lt;/span&gt;&lt;a style=&quot;font-size: 8pt;&quot; href=&quot;https://verve.com/applicant-privacy-policy/&quot; target=&quot;_blank&quot;&gt;privacy policy&lt;/a&gt;&lt;span style=&quot;font-size: 8pt;&quot;&gt; to understand how Verve processes your personal information and how you can exercise your rights.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;Find Jobs in United Kingdom on Arbeitnow

&lt;div class=&quot;content-intro&quot;&gt;&lt;h2&gt;About us&lt;/h2&gt;
&lt;div&gt;&lt;strong&gt;Re-architecting Engineering for the Age of Intelligence&lt;br&gt;&lt;/strong&gt;&lt;br&gt;PhysicsX is the physics AI company for industrials. The company’s mission is to accelerate hardware innovation by overhauling what industrial engineering and manufacturing look like today. PhysicsX is building a new simulation software stack to deliver deep physics AI enablement across the entire engineering lifecycle. The company partners with leading organisations in aerospace &amp;amp; defence, automotive, semiconductors, materials, and energy &amp;amp; renewables, supporting them on some of their most critical and complex challenges. PhysicsX is headquartered in the United Kingdom, with offices in London, New York, and Singapore and an expanding presence in the Bay Area.&lt;/div&gt;&lt;/div&gt;&lt;h4&gt;&amp;nbsp;&lt;/h4&gt;
&lt;h3&gt;&lt;strong&gt;Note: &lt;/strong&gt;We are currently recruiting for multiple positions, however please only apply for the role that best aligns with your skillset and career goals.&lt;/h3&gt;
&lt;h2&gt;&lt;strong&gt;Who We&#39;re Looking For&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;As a Machine Learning Enginee&lt;span class=&quot;discussion-id-26b4aca9-ecb3-80eb-96e7-001ccc66c681 suggestion-update notion-enable-hover&quot; data-token-index=&quot;1&quot;&gt;r &lt;/span&gt;&lt;span class=&quot;discussion-id-26b4aca9-ecb3-8041-9b49-001cc83e32fd suggestion-update notion-enable-hover&quot; data-token-index=&quot;3&quot;&gt;in Delivery&lt;/span&gt;, you are a problem solver and builder who is passionate about creating practical solutions that enable customers to make better engineering decisions. You are someone who can grasp advanced engineering concepts across multiple industries, and you excel at working directly with customers (and often side-by-side with them on-site) to build, deploy and maintain production-grade ML tools that are useful, and used.&lt;/p&gt;
&lt;p&gt;You design, build, and test reliable, scalable machine learning pipelines, and you know when to explore and manipulate 3D point-cloud and mesh data to enable geometry-aware modelling. You create analytics environments and resources in the cloud/on-prem that span data science, selecting the right libraries, frameworks and tools while making pragmatic product decisions that set delivery up for success. You thrive at the intersection of data sicence and software engineering, translating project outputs into tooling and products.&lt;/p&gt;
&lt;p&gt;With at least 1 year industry experience (post Masters or PhD) in a commercial, non-research environment, you’re ready to hit the ground running. You’re truly excited about growing your technical expertise and are naturally inclined to take ownership of MLE pipelines, continuously improving the systems and solutions you work on to ensure they are practical, impactful and meet the evolving customer needs.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h2&gt;This Role&amp;nbsp;&lt;/h2&gt;
&lt;p&gt;In this role, you’ll work closely with our customers, as well as our team of Simulation Engineers, Data Scientists, and Software Engineers, to understand and define the engineering and physics challenges we are solving.&lt;/p&gt;
&lt;p&gt;You’ll build the foundations for successful, impactful solutions by:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Designing, building and testing data/ML pipelines, that are reliable, scalable and easily deployable in production environment.&lt;/li&gt;
&lt;li&gt;Productionising ML models and surrogates with clear validation, error analysis&lt;/li&gt;
&lt;li&gt;Exploring and manipulating 3D point-cloud and mesh data, applying graph/geometry-aware techniques where appropriate&lt;/li&gt;
&lt;li&gt;Working closely with simulation engineers to ensure seamless integration of data science models with simulations.&lt;/li&gt;
&lt;li&gt;Engaging in open communication and presentation with both technical teams and customers, helping onboard users and co-develop with customers.&lt;/li&gt;
&lt;li&gt;There is a requirement to travel to customer sites in North America, Europe, Asia, Oceania, an &lt;strong&gt;average of 3-4 weeks per quarter,&lt;/strong&gt; where you’ll collaborate closely with customers to build solutions on site.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;As the role evolves, there are exciting opportunities for growth as a technical lead, perfect for someone who is driven by taking ownership of more complex projects and leading the direction of future solutions.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Our delivery teams drive innovation to turn AI models into practical solutions - &lt;a href=&quot;https://www.physicsx.ai/newsroom/how-delivery-makes-physical-ai-work-in-the-real-world&quot;&gt;read our blog to learn more about how you’ll contribute to this exciting journey!&lt;/a&gt;&lt;/strong&gt;&lt;a href=&quot;https://www.physicsx.ai/newsroom/how-delivery-makes-physical-ai-work-in-the-real-world&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;We operate on a hybrid model, with around three days per week based in our Shoreditch office.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What we offer&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Build what actually matters&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Help shape an AI-native engineering company at a formative stage, tackling problems that genuinely matter for industry and society. This is work with real-world impact - and something you can be proud to stand behind.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Learn alongside exceptional people&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Work with a high-caliber, collaborative team of engineers, scientists, and operators who care deeply about doing great work, and about helping each other get better. We come from diverse backgrounds, but we share a commitment to operating at the highest level and addressing some of the most complex challenges out there. If you’re ambitious, thoughtful, and driven by impact, you’ll feel at home.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Influence over hierarchy&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We operate with a flat structure: good ideas win&amp;nbsp;- wherever they come from. Questioning assumptions and challenging the status quo isn’t just welcomed, it’s expected.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Sustainable pace, long-term ambition&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Building meaningful technology is a marathon, not a sprint. We believe in balancing focused, ambitious work with a life beyond it. Our hybrid model blends time together in our Shoreditch office with work-from-home days, giving you the flexibility to work sustainably while staying connected in person.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;And it doesn’t stop there …&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;🚀&amp;nbsp;&lt;strong&gt;Equity options&lt;/strong&gt;&amp;nbsp;- share meaningfully in the company you’re helping to build.&lt;/p&gt;
&lt;p&gt;🏦&amp;nbsp;&lt;strong&gt;10% employer pension contribution&lt;/strong&gt;&amp;nbsp;- because investing in future matters.&lt;/p&gt;
&lt;p&gt;🍽️&amp;nbsp;&lt;strong&gt;Free office lunches&lt;/strong&gt;&amp;nbsp;- to keep you energised and focused.&lt;/p&gt;
&lt;p&gt;👶&amp;nbsp;&lt;strong&gt;Enhanced parental leave&lt;/strong&gt;&amp;nbsp;- 3 months full pay paternity and 6 months full pay maternity leave, to provide extra flexibility during the moments that matter most.&lt;/p&gt;
&lt;p&gt;🍼&amp;nbsp;&lt;strong&gt;YellowNest nursery scheme&lt;/strong&gt;&amp;nbsp;- to help working parents manage childcare costs.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;☀️&amp;nbsp;25 days of Annual Leave (+ Public Holidays)&lt;/strong&gt;&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;- because taking time to rest matters.&lt;/p&gt;
&lt;p&gt;🏥&amp;nbsp;&lt;strong&gt;Private medical insurance&lt;/strong&gt;&amp;nbsp;- 100% employee cover, giving you complete peace of mind.&lt;/p&gt;
&lt;p&gt;💪&amp;nbsp;&lt;strong&gt;Wellhub Subscription&lt;/strong&gt;&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;- gain access to thousands of gyms, classes and wellness apps, supporting both physical and mental wellbeing.&lt;/p&gt;
&lt;p&gt;👀&amp;nbsp;&lt;strong&gt;Eye tests&lt;/strong&gt;&amp;nbsp;- because good work depends on good health.&lt;/p&gt;
&lt;p&gt;📈&amp;nbsp;&lt;strong&gt;Personal development&lt;/strong&gt;&amp;nbsp;- dedicated support for learning, development, and leveling up over time.&lt;/p&gt;
&lt;p&gt;💛&amp;nbsp;&lt;strong&gt;Employee Assistance Programme (EAP)&lt;/strong&gt;&amp;nbsp;- confidential wellbeing support, available whenever you need it.&lt;/p&gt;
&lt;p&gt;🚲&amp;nbsp;&lt;strong&gt;Bike2Work scheme and&lt;/strong&gt;&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;🚆&amp;nbsp;&lt;strong&gt;Season ticket loan&lt;/strong&gt;&amp;nbsp;- to make getting to work easier and greener.&lt;/p&gt;
&lt;p&gt;🚗&amp;nbsp;&lt;strong&gt;Octopus EV salary sacrifice&lt;/strong&gt;&amp;nbsp;- for a simpler, more sustainable way to drive electric.&lt;/p&gt;
&lt;p&gt;&lt;em&gt;🔎&amp;nbsp;Watch this space, we’re continuing to build this as we grow…&lt;/em&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;We value diversity and are committed to equal employment opportunity regardless of sex, race, religion, ethnicity, nationality, disability, age, sexual orientation or gender identity. We strongly encourage individuals from groups traditionally underrepresented in tech to apply. To help make a change, we sponsor bright women from disadvantaged backgrounds through their university degrees in science and mathematics.&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;We collect diversity and inclusion data solely for the purpose of monitoring the effectiveness of our equal opportunities policies and ensuring compliance with employment and equality legislation. This information is confidential, used only in aggregate form, and will not influence the outcome of your application.&amp;nbsp;&lt;/div&gt;
